import java.util.*
import kotlin.math.sqrt

fun main() {
    val n = readLine()!!.toInt()
    var bestA = 1
    var bestB = n
    val sqrtN = sqrt(n.toDouble()).toInt()
    for (a in 1..sqrtN) {
        if (n % a == 0) {
            val b = n / a
            if (a <= b && (b - a) < (bestB - bestA)) {
                bestA = a
                bestB = b
            }
        }
    }
    println("$bestA $bestB")
}
